<style>
.tech-heading{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;margin-bottom:12px}.tech-heading h1{font-size:23px}.tech-heading p{font-size:12px;margin:4px 0;color:var(--t-muted)}.tech-tabs{display:flex;gap:8px;flex-wrap:wrap}.tech-tabs a{padding:10px 14px;border:1px solid var(--t-border);border-radius:8px;color:var(--t-ink)}.tech-tabs a[aria-current=page]{background:var(--t-button);color:var(--t-button-ink)}.tech-search{display:flex;gap:8px;margin-bottom:12px;flex-wrap:wrap}.tech-search input{flex:1;min-width:120px}.tech-workspace{display:grid;grid-template-columns:minmax(0,1fr) minmax(300px,36%);gap:14px;flex:1;min-height:0;overflow:hidden}.tech-list{overflow:auto;min-height:0;display:grid;align-content:start;gap:12px;padding-right:5px}.tech-job{padding:15px;border:1px solid var(--t-border);border-radius:10px;background:var(--t-surface);color:var(--t-ink)}.tech-job h2{margin:4px 0 8px;font-size:16px}.tech-job p{font-size:12px;margin:6px 0}.tech-job small{color:var(--t-muted)}.tech-status{display:inline-block;padding:4px 8px;border-radius:14px;background:var(--t-alt);font-size:11px}.tech-detail{overflow:auto;min-height:0;padding:18px;border:1px solid var(--t-border);border-radius:10px;background:var(--t-surface)}.tech-detail h2{font-size:18px;margin-top:0}.tech-detail p{white-space:pre-wrap;overflow-wrap:anywhere}.tech-detail textarea{min-height:110px;resize:vertical}.tech-detail button{width:100%;min-height:44px;margin-top:12px}.tech-pages{display:flex;gap:12px;align-items:center;padding:8px 0;flex-shrink:0;font-size:12px}.tech-parts{grid-template-columns:repeat(auto-fill,minmax(220px,1fr));overflow:auto;min-height:0;display:grid;gap:12px;align-content:start;flex:1}.tech-qty{font-size:22px;font-weight:800;margin-top:12px}
body:has(.tech-heading) #ccsPageContent{display:flex!important;flex-direction:column!important;min-height:0!important;overflow:hidden!important}body:has(.tech-heading) .wrap,body:has(.tech-heading) .wrap>main{height:calc(100dvh - var(--v82-keyboard-height,0px));min-height:0!important;overflow:hidden!important}body:has(.tech-heading) main{display:flex;flex-direction:column}body:has(.tech-heading) main>footer{display:none}
@media(max-width:950px){.tech-workspace{grid-template-columns:1fr;overflow:auto}.tech-list{max-height:45dvh;flex:none}.tech-detail{max-height:60dvh}.tech-job{padding:12px}.tech-heading h1{font-size:20px}}
@media print{.tech-heading,.tech-search,.tech-tabs,.tech-pages{display:none}.tech-workspace,.tech-detail{height:auto;max-height:none;overflow:visible}}
</style>
